/*******************************************************************************
 * mc_font_latin_18: Montserrat Medium 18 px, 4 bpp, Latin-1 Supplement + Latin Extended-A
 * (U+00A0..U+017F: German, Polish, Czech, French, Spanish, Portuguese, ...) plus the
 * punctuation phones insert ( – — ‘ ’ “ ” „ • … € ). No ASCII, no LV_SYMBOL_*:
 * `.fallback` points at the built-in lv_font_montserrat_18, which serves those.
 *
 * Generated (CHARS-01 Part B), from lib/lvgl/scripts/built_in_font/:
 *   npx lv_font_conv --no-compress --no-prefilter --bpp 4 --size 18 \
 *     --font Montserrat-Medium.ttf -r 0xA0-0x17F \
 *     -r 0x2013,0x2014,0x2018,0x2019,0x201C,0x201D,0x201E,0x2022,0x2026,0x20AC \
 *     --format lvgl --force-fast-kern-format -o mc_font_latin_18.c
 * Never --lcd: sub-pixel fonts render blank with LV_USE_FONT_SUBPX 0
 * (tools/tests/test_tdeck_fonts.py).
 * Post-edit: `.fallback = &lv_font_montserrat_18` (was NULL), the extern declaration
 * and `#include <lvgl.h>`.
 * Compiled only in T-Deck builds (src/t-deck/ is excluded from every other env).
 *
 * Font: Montserrat, Copyright The Montserrat Project Authors, SIL Open Font License 1.1
 * (https://openfontlicense.org). Generated bitmaps are embedded in the firmware binary.
 ******************************************************************************/

